/**
 * The event writer against real PostgreSQL.
 *
 * Four of T13's properties cannot be established without a server: that an
 * event rolls back with its surrounding transaction, that it commits with one,
 * that `server_ts` is generated by the database, and that a cross-tenant append
 * is genuinely refused rather than merely intercepted in TypeScript. Those are
 * here; everything provable without a database is in
 * `src/common/events/*.spec.ts`.
 *
 * This lives in `scripts/` rather than `db/` on purpose. The T13 validation
 * step reads `git status -- apps/api/db/` as the signal for "no schema or
 * migration change", and a new file in that directory would muddy it.
 *
 * It runs entirely inside one transaction that is rolled back at the end, so
 * the database is left exactly as it was found — the same approach as
 * `db/verify.mjs`. Nested transactions (savepoints) provide the inner
 * commit/rollback boundaries.
 *
 *   pnpm --filter @vcip/api db:verify-events
 */

import { randomUUID } from 'node:crypto';
import { sql } from 'drizzle-orm';
import { drizzle } from 'drizzle-orm/postgres-js';
import postgres from 'postgres';
import { SessionEventType } from '@vcip/shared';
import type { DbExecutor } from '../src/common/events/session-event.writer.js';
import {
  DrizzleSessionEventWriter,
  EventTenantMismatchError,
} from '../src/common/events/session-event.writer.js';
import { ProhibitedEventPayloadError } from '../src/common/events/event-payload.js';

let passed = 0;
let failed = 0;

const check = (condition: boolean, label: string): void => {
  if (condition) {
    passed += 1;
    process.stdout.write(`   PASS  ${label}\n`);
  } else {
    failed += 1;
    process.stdout.write(`   FAIL  ${label}\n`);
  }
};

const section = (label: string): void => {
  process.stdout.write(`\n${label}\n`);
};

async function main(): Promise<void> {
  const url = process.env['DATABASE_URL'];
  if (url === undefined || url.trim().length === 0) {
    process.stdout.write('DATABASE_URL is not set.\n');
    process.exit(1);
  }

  const client = postgres(url, { max: 1 });
  const db = drizzle(client);
  const writer = new DrizzleSessionEventWriter();

  // Every id is fresh, so a run cannot collide with seeded data or with itself.
  const tenantA = randomUUID();
  const tenantB = randomUUID();
  const sessionId = randomUUID();
  const agentUserId = randomUUID();

  try {
    await db.transaction(async (tx) => {
      // ------------------------------------------------------- fixtures
      await tx.execute(sql`
        INSERT INTO tenants (id, slug, name, status)
        VALUES (${tenantA}::uuid, ${'t13-a-' + tenantA}, 'T13 scratch A', 'ACTIVE'),
               (${tenantB}::uuid, ${'t13-b-' + tenantB}, 'T13 scratch B', 'ACTIVE')`);

      await tx.execute(sql`
        INSERT INTO sessions (id, tenant_id, external_ref, status, language, room_name)
        VALUES (${sessionId}::uuid, ${tenantA}::uuid, 't13-scratch', 'CREATED', 'en',
                ${'vcip_' + sessionId})`);

      const countEvents = async (executor: DbExecutor): Promise<number> => {
        const rows = await executor.execute(
          sql`SELECT count(*)::text AS n FROM session_events WHERE session_id = ${sessionId}::uuid`,
        );
        return Number(rows[0]?.['n'] ?? '0');
      };

      // ------------------------------------------------- [1] basic append
      section('[1] A valid event is inserted with every column intact');
      const written = await writer.append(
        {
          tenantId: tenantA,
          sessionId,
          eventType: SessionEventType.SESSION_CREATED,
          actorType: 'ENTERPRISE',
          actorId: null,
          payload: { language: 'en' },
        },
        tx,
      );

      const stored = await tx.execute<{
        tenant_id: string;
        session_id: string;
        event_type: string;
        actor_type: string;
        actor_id: string | null;
        payload: Record<string, unknown>;
        server_ts: Date;
      }>(sql`SELECT * FROM session_events WHERE id = ${written.id}::bigint`);

      const row = stored[0];
      check(row !== undefined, 'the event row exists');
      check(row?.tenant_id === tenantA, 'tenant_id is persisted');
      check(row?.session_id === sessionId, 'session_id is persisted');
      check(row?.event_type === 'SESSION_CREATED', 'event_type comes from the shared contract');
      check(row?.actor_type === 'ENTERPRISE', 'actor_type is persisted');
      check(row?.actor_id === null, 'actor_id is null for an enterprise actor');
      check(row?.payload['language'] === 'en', 'payload is persisted as JSONB');

      // -------------------------------------------- [2] server timestamp
      section('[2] server_ts is generated by the database');
      // `execute` returns driver-shaped rows, so a timestamptz may arrive as a
      // string rather than a Date depending on the parser in play. Coerce
      // rather than assume — the assertion is about the instant, not the type.
      const asDate = (value: unknown): Date =>
        value instanceof Date ? value : new Date(String(value));

      const clock = await tx.execute<{ now: unknown }>(sql`SELECT now() AS now`);
      const dbNow = asDate(clock[0]?.now);
      const storedTs = asDate(row?.server_ts);
      check(!Number.isNaN(storedTs.getTime()), 'server_ts is a valid timestamp');
      check(
        Math.abs(dbNow.getTime() - storedTs.getTime()) < 60_000,
        'server_ts matches the database clock, not a caller value',
      );

      const smuggled = await writer.append(
        {
          tenantId: tenantA,
          sessionId,
          eventType: SessionEventType.CONSENT_ACCEPTED,
          actorType: 'CUSTOMER',
          actorId: null,
          payload: { accepted: true },
          // Cast past the input type, which has no timestamp field at all.
          serverTs: new Date('1999-01-01T00:00:00.000Z'),
        } as never,
        tx,
      );
      check(
        new Date(String(smuggled.serverTs)).getUTCFullYear() > 2020,
        'a caller-supplied timestamp is ignored entirely',
      );

      // ------------------------------------------ [3] tenant ownership
      section('[3] A cross-tenant append is refused by the INSERT itself');
      const before = await countEvents(tx);
      let refused = false;
      try {
        await writer.append(
          {
            // Tenant B does not own this session.
            tenantId: tenantB,
            sessionId,
            eventType: SessionEventType.SESSION_ABORTED,
            actorType: 'SYSTEM',
            actorId: null,
            payload: { from: 'CREATED', to: 'ABORTED' },
          },
          tx,
        );
      } catch (error) {
        refused = error instanceof EventTenantMismatchError;
      }
      check(refused, 'the writer refuses a session that belongs to another tenant');
      check((await countEvents(tx)) === before, 'no row was written under the wrong tenant');

      const foreignRows = await tx.execute<{ n: string }>(
        sql`SELECT count(*)::text AS n FROM session_events WHERE tenant_id = ${tenantB}::uuid`,
      );
      check(Number(foreignRows[0]?.n ?? '0') === 0, 'tenant B has no events at all');

      let missingRefused = false;
      try {
        await writer.append(
          {
            tenantId: tenantA,
            sessionId: randomUUID(),
            eventType: SessionEventType.SESSION_CREATED,
            actorType: 'SYSTEM',
            actorId: null,
            payload: {},
          },
          tx,
        );
      } catch (error) {
        missingRefused = error instanceof EventTenantMismatchError;
      }
      check(missingRefused, 'a nonexistent session is refused the same way');

      // ----------------------------------------- [4] multiple events
      section('[4] Multiple events accumulate on one session');
      await writer.append(
        {
          tenantId: tenantA,
          sessionId,
          eventType: SessionEventType.PREFLIGHT_PASSED,
          actorType: 'CUSTOMER',
          actorId: null,
          payload: { measurements: { camera_width: 1280 } },
        },
        tx,
      );
      await writer.append(
        {
          tenantId: tenantA,
          sessionId,
          eventType: SessionEventType.AGENT_ACCEPTED,
          actorType: 'AGENT',
          actorId: agentUserId,
          payload: {},
        },
        tx,
      );

      const ordered = await tx.execute<{ event_type: string; actor_id: string | null }>(
        sql`SELECT event_type, actor_id FROM session_events
             WHERE session_id = ${sessionId}::uuid ORDER BY id`,
      );
      check(ordered.length === 4, 'all four events are present');
      check(
        ordered.map((e) => e.event_type).join(',') ===
          'SESSION_CREATED,CONSENT_ACCEPTED,PREFLIGHT_PASSED,AGENT_ACCEPTED',
        'events are readable in append order, and none replaced another',
      );
      check(
        ordered[3]?.actor_id === agentUserId,
        'actor_id carries the user id for an agent actor',
      );

      // ------------------------------------- [5] transaction rollback
      section('[5] An event rolls back with its surrounding transaction');
      const beforeRollback = await countEvents(tx);
      let rolledBack = false;
      // Was the row actually there before the rollback? Without this, the check
      // below cannot tell "written, then rolled back" from "never written at
      // all" — and a writer that ignored the transaction it was handed would
      // pass by failing early. Asserting visibility INSIDE the transaction is
      // what makes the rollback assertion mean something.
      let visibleInsideTransaction = false;
      try {
        await tx.transaction(async (inner) => {
          await writer.append(
            {
              tenantId: tenantA,
              sessionId,
              eventType: SessionEventType.SESSION_ABORTED,
              actorType: 'CUSTOMER',
              actorId: null,
              payload: { from: 'CREATED', to: 'ABORTED' },
            },
            inner,
          );
          visibleInsideTransaction = (await countEvents(inner)) === beforeRollback + 1;
          // The business operation fails after the event was appended. Both
          // must disappear together.
          throw new Error('business failure after append');
        });
      } catch {
        rolledBack = true;
      }
      check(rolledBack, 'the surrounding transaction failed');
      check(
        visibleInsideTransaction,
        'the event was written inside the caller transaction, not on a separate connection',
      );
      check(
        (await countEvents(tx)) === beforeRollback,
        'the event rolled back with it and left no trace',
      );

      // --------------------------------------- [6] transaction commit
      section('[6] An event commits with its surrounding transaction');
      await tx.transaction(async (inner) => {
        await writer.append(
          {
            tenantId: tenantA,
            sessionId,
            eventType: SessionEventType.LOCATION_PASSED,
            actorType: 'CUSTOMER',
            actorId: null,
            payload: { gps_accuracy_m: 25, ip_country: 'IN' },
          },
          inner,
        );
      });
      check(
        (await countEvents(tx)) === beforeRollback + 1,
        'the event is visible once the surrounding transaction commits',
      );

      // ------------------------------- [7] atomicity with a state change
      section('[7] A session update and its event are one unit');
      let bothRolledBack = false;
      try {
        await tx.transaction(async (inner) => {
          await inner.execute(
            sql`UPDATE sessions SET status = 'QUEUED' WHERE id = ${sessionId}::uuid`,
          );
          await writer.append(
            {
              tenantId: tenantA,
              sessionId,
              eventType: SessionEventType.SESSION_QUEUED,
              actorType: 'CUSTOMER',
              actorId: null,
              payload: {},
            },
            inner,
          );
          throw new Error('failure after both writes');
        });
      } catch {
        bothRolledBack = true;
      }
      const statusRows = await tx.execute<{ status: string }>(
        sql`SELECT status FROM sessions WHERE id = ${sessionId}::uuid`,
      );
      const queuedEvents = await tx.execute<{ n: string }>(
        sql`SELECT count(*)::text AS n FROM session_events
             WHERE session_id = ${sessionId}::uuid AND event_type = 'SESSION_QUEUED'`,
      );
      check(bothRolledBack, 'the combined operation failed');
      check(statusRows[0]?.status === 'CREATED', 'the status change rolled back');
      check(
        Number(queuedEvents[0]?.n ?? '0') === 0,
        'the event rolled back too — no orphan history for a change that never happened',
      );

      // --------------------------------- [8] prohibited payload content
      section('[8] A prohibited payload never reaches the database');
      const beforeProhibited = await countEvents(tx);
      let prohibited = false;
      try {
        await writer.append(
          {
            tenantId: tenantA,
            sessionId,
            eventType: SessionEventType.LOCATION_PASSED,
            actorType: 'CUSTOMER',
            actorId: null,
            payload: { latitude: 28.6139, longitude: 77.209 },
          },
          tx,
        );
      } catch (error) {
        prohibited = error instanceof ProhibitedEventPayloadError;
      }
      check(prohibited, 'a payload carrying coordinates is rejected');
      check(
        (await countEvents(tx)) === beforeProhibited,
        'nothing was written, so the transaction stays usable',
      );

      const anyCoords = await tx.execute<{ n: string }>(
        sql`SELECT count(*)::text AS n FROM session_events
             WHERE session_id = ${sessionId}::uuid
               AND payload::text ~* 'latitude|longitude|28\\.61|77\\.20'`,
      );
      check(
        Number(anyCoords[0]?.n ?? '0') === 0,
        'no event for this session contains a coordinate',
      );

      // ------------------------------------------- [9] append-only shape
      section('[9] The writer offers no way to rewrite history');
      const surface = Object.getOwnPropertyNames(DrizzleSessionEventWriter.prototype).filter(
        (name) => name !== 'constructor',
      );
      check(
        surface.length === 1 && surface[0] === 'append',
        `the writer exposes only append (found: ${surface.join(', ')})`,
      );

      // Roll the whole thing back: this script leaves nothing behind.
      throw new Error('__rollback__');
    });
  } catch (error) {
    if (!(error instanceof Error) || error.message !== '__rollback__') {
      process.stdout.write(`\nUNEXPECTED ERROR: ${String(error)}\n`);
      failed += 1;
    }
  }

  // Confirm the rollback actually happened.
  const leftovers = await db.execute<{ n: string }>(
    sql`SELECT count(*)::text AS n FROM session_events WHERE session_id = ${sessionId}::uuid`,
  );
  section('[10] The script leaves the database as it found it');
  check(Number(leftovers[0]?.n ?? '0') === 0, 'no scratch events remain');

  const leftoverTenants = await db.execute<{ n: string }>(
    sql`SELECT count(*)::text AS n FROM tenants WHERE id IN (${tenantA}::uuid, ${tenantB}::uuid)`,
  );
  check(Number(leftoverTenants[0]?.n ?? '0') === 0, 'no scratch tenants remain');

  await client.end();

  process.stdout.write(
    failed === 0
      ? `\nALL EVENT WRITER CHECKS PASSED (${passed})\n`
      : `\n${failed} CHECK(S) FAILED (${passed} passed)\n`,
  );
  process.exit(failed === 0 ? 0 : 1);
}

void main();
